export function operationHandlerFor(operation:string):OperationHandlerSpec{const spec=byOperation.get(operation);if(!spec)throw new Error(`OPERATION_HANDLER_NOT_BOUND:${operation}`);return spec;}
export function assertOperationHandlerCoverage(contracts:readonly OperationContract[]):void{
 const expected=new Map(contracts.map(contract=>[contract.operationName,contract]));
 if(expected.size!==operationHandlerCatalog.length)throw new Error(`OPERATION_HANDLER_COUNT_MISMATCH:contract=${expected.size}:handler=${operationHandlerCatalog.length}`);
 for(const spec of operationHandlerCatalog){const contract=expected.get(spec.operation);if(!contract)throw new Error(`OPERATION_HANDLER_UNKNOWN:${spec.operation}`);if(contract.canonicalDigest!==spec.contractDigest||contract.operationFamily!==spec.family)throw new Error(`OPERATION_HANDLER_STALE:${spec.operation}`);}
}
